#pragma once
#include <stdint.h>

namespace NeighbourContactCleanup {
// Only the exact, untouched signature generated by the retired importer.
constexpr bool isPlaceholderName(const char* name, const uint8_t* key) {
  if (!name || !key) return false;
  constexpr char prefix[] = "Repeater_";
  constexpr char hex[] = "0123456789ABCDEF";
  for (unsigned i = 0; i < 9; ++i) {
    if (name[i] != prefix[i]) return false;
  }
  for (unsigned i = 0; i < 4; ++i) {
    if (name[9 + 2 * i] != hex[key[i] >> 4] ||
        name[10 + 2 * i] != hex[key[i] & 15]) return false;
  }
  return name[17] == '\0';
}

constexpr bool shouldRemove(const char* name, const uint8_t* key, bool is_repeater,
                            uint32_t last_advert, int32_t lat, int32_t lon,
                            uint8_t flags, bool has_saved_route) {
  return is_repeater && last_advert == 0 && lat == 0 && lon == 0 &&
         flags == 0 && !has_saved_route && isPlaceholderName(name, key);
}
}
